Algorithm 1: Association-based Decomposition
(PMI/LLR/t-score)
Input: document D, n-gram sets B, T , Q, stopwords S
Output: chunk sequence C
1 C ←[ ];
2 sentences ←SentenceTokenize(D);
3 foreach sentence ∈sentences do
4
tokens ←WordTokenize(sentence, pattern =
\b\w + \b);
5
tokens ←Lowercase(tokens);
6
i ←0;
7
while i < |tokens| do
8
matched ←False;
9
if i + 3 < |tokens| then
10
ngram ←Join(tokens[i : i + 4], " ");
11
if ngram ∈Q then
12
C.extend(ProcessStopwords(tokens[i :
i + 4], S));
13
i ←i + 4;
14
matched ←True;
15
continue;
16
if ¬matched ∧i + 2 < |tokens| then
17
ngram ←Join(tokens[i : i + 3], " ");
18
if ngram ∈T then
19
C.extend(ProcessStopwords(tokens[i :
i + 3], S));
20
i ←i + 3;
21
matched ←True;
22
continue;
23
if ¬matched ∧i + 1 < |tokens| then
24
ngram ←Join(tokens[i : i + 2], " ");
25
if ngram ∈B then
26
C.extend(ProcessStopwords(tokens[i :
i + 2], S));
27
i ←i + 2;
28
matched ←True;
29
continue;
30
C.append(tokens[i]);
31
i ←i + 1;
32 C ←MergeContractions(C);
33 return C;
Algorithm 2: POS-based Decomposition
with BigramTagger
Input: document D, trained BigramTagger θ, stopwords S
Output: chunk sequence C
1 C ←[ ];
2 sentences ←SentenceTokenize(D);
3 foreach sentence ∈sentences do
4
tokens ←WordTokenize(sentence);
5
tokens ←Lowercase(tokens);
6
pos_tags ←POSTagger(tokens);
7
chunk_tags ←θ.tag(pos_tags);
8
tree ←ParseIOB(tokens, pos_tags, chunk_tags);
9
foreach subtree ∈tree do
10
if IsChunk(subtree) then
11
words ←ExtractWords(subtree);
12
processed ←ProcessStopwords(words, S);
13
C.extend(processed);
14
else
15
word ←ExtractWord(subtree);
16
C.append(word);
17 C ←MergeContractions(C);
18 return C;
Algorithm 3: WordNet-based Decomposi-
tion
Input: document D, WordNet database W, stopwords S
Output: chunk sequence C
1 C ←[ ];
2 sentences ←SentenceTokenize(D);
3 foreach sentence ∈sentences do
4
tokens ←WordTokenize(sentence);
5
tokens ←Lowercase(tokens);
6
i ←0;
7
while i < |tokens| do
8
matched ←False;
9
if i + 3 < |tokens| then
10
lemma ←Join(tokens[i : i + 4], "_");
11
if W.synsets(lemma) ̸= ∅then
12
C.extend(ProcessStopwords(tokens[i :
i + 4], S));
13
i ←i + 4;
14
matched ←True;
15
continue;
16
if ¬matched ∧i + 2 < |tokens| then
17
lemma ←Join(tokens[i : i + 3], "_");
18
if W.synsets(lemma) ̸= ∅then
19
C.extend(ProcessStopwords(tokens[i :
i + 3], S));
20
i ←i + 3;
21
matched ←True;
22
continue;
23
if ¬matched ∧i + 1 < |tokens| then
24
lemma ←Join(tokens[i : i + 2], "_");
25
if W.synsets(lemma) ̸= ∅then
26
C.extend(ProcessStopwords(tokens[i :
i + 2], S));
27
i ←i + 2;
28
matched ←True;
