Algorithm 4: Extract Attention Weights
Input: text T , privacy budget ϵ
Output: token-budget pairs (wi, ϵi)
1 tokens ←BertTokenizer(T );
2 inputs ←prepare_inputs(tokens);
3 outputs ←BertModel(inputs);
4 A ←outputs.attentions;
5 Aavg ←mean(A, dim = (layers, heads));
6 scores ←mean(Aavg, dim = tokens);
7 scored_tokens ←zip(tokens, scores);
8 combined ←combine_subwords(scored_tokens);
9 filtered ←remove(combined, special_tokens);
10 budgets ←normalize_and_distribute(filtered, ϵ);
11 return budgets;
14

Algorithm 5: Extract Integrated Gradients
Input: text T , privacy budget ϵ
Output: token-budget pairs (wi, ϵi)
1 tokens ←BertTokenizer(T );
2 E ←BertEmbeddings(tokens);
3 Function ForwardFunc(E):
4
H ←BertModel(inputs_embeds = E);
5
return mean(H).sum();
6 attributions ←IntegratedGradients(ForwardFunc, E);
7 scores ←||attributions||2;
8 scored_tokens ←zip(tokens, scores);
9 combined ←combine_subwords(scored_tokens);
10 filtered ←remove(combined, special_tokens);
11 budgets ←normalize_and_distribute(filtered, ϵ);
12 return budgets;
Algorithm 6: Get Information Content
Input: text T , privacy budget ϵ
Output: token-budget pairs (wi, ϵi)
1 tokens ←tokenize(T );
2 pos_tags ←pos_tag(tokens);
3 foreach (wi, posi) ∈pos_tags do
4
wn_pos ←convert_to_wordnet(posi);
5
sense ←Lesk(tokens, wi, wn_pos);
6
if sense ̸= null then
7
ic_values ←[ ];
8
foreach corpus ∈IC_corpora do
9
ic_values.append(IC(sense, corpus));
10
scorei ←mean(ic_values);
11
else
12
scorei ←1.0;
13 filtered ←filter_alphanumeric(scored_tokens);
14 budgets ←normalize_and_distribute(filtered, ϵ);
15 return budgets;
Algorithm 7: Convert Scores to Budget
Distribution
Input: scored tokens (ti, si), original text T , privacy budget ϵ,
invert flag
Output: token-budget pairs (wi, ϵi)
1 original_words ←tokenize(T );
2 score_map ←dict(scored_tokens);
3 scores ←[ ];
4 foreach word ∈original_words do
5
if word ∈stopwords then
6
scores.append(0.0);
7
else
8
score ←score_map.get(word, 0.0);
9
scores.append(score);
10 if ∃s ∈scores : s < 0 then
11
min_val ←min({s | s ̸= 0});
12
foreach si ∈scores where si ̸= 0 do
13
si ←si + |min_val|;
14 if invert = True then
15
non_zero_scores ←{s | s > 0};
16
min_nz ←min(non_zero_scores);
17
max_nz ←max(non_zero_scores);
18
if max_nz = min_nz then
19
inverted ←ones(length(non_zero_scores));
20
else
21
inverted ←(max_nz + min_nz) −non_zero_scores;
22
budgets ←(inverted/ P inverted) × ϵ;
23 else
24
total ←P scores;
25
if total > 0 then
26
budgets ←(scores/total) × ϵ;
27 return zip(original_words, budgets);
Algorithm 8: Get Chunked Budgets
Input: clean text Tclean, chunker, distributor, privacy budget ϵ
Output: chunk-budget pairs (ci, ϵi), chunks list C
1 chunked_sentences ←chunker.chunk(Tclean);
2 C ←flatten(chunked_sentences);
3 word_budgets ←distributor.distribute(Tclean, ϵ);
4 budget_iter ←iterator(word_budgets);
5 chunk_budgets ←[ ];
6 foreach chunk ∈C do
7
words ←split(chunk, ‘_’);
8
n ←|words|;
9
ϵchunk ←0.0;
10
for i ←1 to n do
11
(w, ϵw) ←next(budget_iter);
12
ϵchunk ←ϵchunk + ϵw;
13
chunk_budgets.append((chunk, ϵchunk));
14 return chunk_budgets, C;
